/* ============================================================
   LexiAudit — логика приложения
   Разделы: состояние, карточки, тест, глоссарий, диалоги, аудио
   ============================================================ */
"use strict";

/* ---------- вспомогательные ---------- */
const $ = id => document.getElementById(id);
const LS = {
  get(k, d){ try{ const v = JSON.parse(localStorage.getItem(k)); return v === null || v === undefined ? d : v; }catch(e){ return d; } },
  set(k, v){ try{ localStorage.setItem(k, JSON.stringify(v)); }catch(e){} }
};

/* ---------- состояние ---------- */
const state = {
  view: 'cards',
  deck: LS.get('la_deck', 'all'),
  mode: LS.get('la_mode', 'ko-ru'),
  idx: 0,
  items: [],
  favs: new Set(LS.get('la_favs', [])),
  learned: new Set(LS.get('la_learned', [])),
  ttsStyle: LS.get('la_tts', 'natural'),
  search: '',
  quiz: null,
  quote: LS.get('la_quote', null)
};
let curSide = { text:'', lang:'ko-KR' };

/* ---------- озвучка ---------- */
function speak(text, lang){
  if (!('speechSynthesis' in window)) return;
  speechSynthesis.cancel();
  const u = new SpeechSynthesisUtterance(text);
  u.lang = lang || 'ko-KR';
  if (state.ttsStyle === 'soft'){ u.rate = .85; u.pitch = .8; }
  else if (state.ttsStyle === 'energetic'){ u.rate = 1.15; u.pitch = 1.3; }
  else { u.rate = 1; u.pitch = 1; }
  speechSynthesis.speak(u);
}
function speakSide(side){
  const item = state.items[state.idx];
  if (!item) return;
  if (side === 'front') speak(curSide.text, curSide.lang);
  else {
    const koFirst = state.mode !== 'ru-ko';
    speak(koFirst ? item.ko : item.ru, koFirst ? 'ko-KR' : 'ru-RU');
  }
}
function speakEx(){ const it = state.items[state.idx]; if (it && it.exKor) speak(it.exKor, 'ko-KR'); }
function setTTSStyle(style){
  state.ttsStyle = style; LS.set('la_tts', style);
  document.querySelectorAll('.tts-btn').forEach(b => b.classList.toggle('active', b.dataset.style === style));
}

/* ---------- тема ---------- */
function applyTheme(t){
  document.body.dataset.theme = t;
  LS.set('la_theme', t);
}
$('themeBtn').addEventListener('click', () => {
  applyTheme(document.body.dataset.theme === 'dark' ? 'light' : 'dark');
});

/* ---------- данные / фильтры ---------- */
function deckItems(key){
  if (key === 'all') return GLOSSARY.slice();
  if (key === 'favorites') return GLOSSARY.filter(g => state.favs.has(g.ko));
  return GLOSSARY.filter(g => g.deck === key);
}
function refreshItems(){
  state.items = deckItems(state.deck);
  if (state.idx >= state.items.length) state.idx = 0;
}
function deckMeta(key){ return DECKS[key] || DECKS.all; }

/* ---------- шапка: статистика ---------- */
function updateStats(){
  $('topStats').innerHTML =
    `<span class="stat-chip">📚 Всего: <b>${GLOSSARY.length}</b></span>` +
    `<span class="stat-chip">✅ Изучено: <b>${state.learned.size}</b></span>` +
    `<span class="stat-chip">⭐ Избранных: <b>${state.favs.size}</b></span>`;
  $('footCount').textContent = `${GLOSSARY.length} терминов · ${Object.keys(DECKS).filter(k=>k!=='all'&&k!=='favorites').length} колод`;
}

/* ---------- колоды-фильтры ---------- */
function buildChips(){
  const counts = {};
  GLOSSARY.forEach(g => counts[g.deck] = (counts[g.deck] || 0) + 1);
  const keys = ['all'].concat(Object.keys(DECKS).filter(k => k !== 'all' && k !== 'favorites')).concat(['favorites']);
  ['deckChips', 'deckChips2'].forEach(cid => {
    const box = $(cid);
    box.innerHTML = '';
    keys.forEach(k => {
      const n = k === 'all' ? GLOSSARY.length : (k === 'favorites' ? state.favs.size : (counts[k] || 0));
      const b = document.createElement('button');
      b.className = 'chip' + (state.deck === k ? ' active' : '');
      b.dataset.deck = k;
      const d = deckMeta(k);
      b.innerHTML = `${d.icon} ${d.label} <i>${n}</i>`;
      b.onclick = () => selectDeck(k);
      box.appendChild(b);
    });
  });
}
function selectDeck(k){
  state.deck = k; state.idx = 0;
  LS.set('la_deck', k);
  refreshItems(); buildChips(); renderCard(); renderGlossary(); renderListen();
  if (state.view === 'quiz') buildQuiz(true);
}

/* ---------- карточки ---------- */
function renderCard(){
  const card = $('cardEl');
  card.classList.remove('flipped');
  const items = state.items;

  if (!items.length){
    $('frontTerm').textContent = 'Список пуст';
    $('backTerm').textContent = '';
    $('frontBadge').style.display = 'none';
    $('backBadge').style.display = 'none';
    $('backHint').textContent = 'Добавляйте карточки в избранное кнопкой ☆ на карточке или в глоссарии.';
    $('backExample').style.display = 'none';
    $('progressText').textContent = '0 / 0';
    $('deckProgressText').textContent = '—';
    $('deckProgressBar').style.width = '0%';
    document.querySelectorAll('.fav-btn').forEach(b => { b.classList.remove('active'); b.textContent = '☆'; });
    updateStats();
    return;
  }

  const item = items[state.idx];
  const koFirst = state.mode !== 'ru-ko';
  curSide = koFirst ? { text: item.ko, lang: 'ko-KR' } : { text: item.ru, lang: 'ru-RU' };

  $('frontTerm').textContent = curSide.text;
  $('backTerm').textContent = koFirst ? item.ru : item.ko;
  $('backHint').textContent = item.hint || '';

  const ex = $('backExample');
  if (item.exKor){
    $('exKor').textContent = item.exKor;
    $('exRus').textContent = item.exRus || '';
    ex.style.display = '';
  } else { ex.style.display = 'none'; }

  // бейджи колоды
  const fb = $('frontBadge'), bb = $('backBadge');
  const d = deckMeta(item.deck);
  [fb, bb].forEach(b => {
    b.style.display = '';
    b.style.background = d.color + '1f';
    b.style.color = d.color;
    b.style.border = '1px solid ' + d.color + '55';
    b.textContent = d.icon + ' ' + d.label;
  });

  // избранное и «знаю»
  const favActive = state.favs.has(item.ko);
  document.querySelectorAll('.fav-btn').forEach(b => { b.classList.toggle('active', favActive); b.textContent = favActive ? '★' : '☆'; });
  document.querySelectorAll('.know-btn').forEach(b => b.classList.toggle('active', state.learned.has(item.ko)));

  // прогресс
  $('progressText').textContent = `${state.idx + 1} / ${items.length}`;
  const total = deckItems(state.deck).length;
  const known = deckItems(state.deck).filter(g => state.learned.has(g.ko)).length;
  $('deckProgressText').textContent = `Изучено ${known} из ${total}`;
  $('deckProgressBar').style.width = total ? (known / total * 100) + '%' : '0%';

  updateStats();
}
function nextCard(){ if (!state.items.length) return; state.idx = (state.idx + 1) % state.items.length; renderCard(); }
function prevCard(){ if (!state.items.length) return; state.idx = (state.idx - 1 + state.items.length) % state.items.length; renderCard(); }
function randCard(){ if (!state.items.length) return; if (state.items.length > 1){ let n; do { n = Math.floor(Math.random() * state.items.length); } while (n === state.idx); state.idx = n; } renderCard(); }

function toggleFav(){
  const item = state.items[state.idx];
  if (!item) return;
  state.favs.has(item.ko) ? state.favs.delete(item.ko) : state.favs.add(item.ko);
  LS.set('la_favs', [...state.favs]);
  if (state.deck === 'favorites'){ refreshItems(); }
  renderCard(); renderGlossary(); buildChips(); updateStats();
}
function toggleLearned(){
  const item = state.items[state.idx];
  if (!item) return;
  state.learned.has(item.ko) ? state.learned.delete(item.ko) : state.learned.add(item.ko);
  LS.set('la_learned', [...state.learned]);
  renderCard(); updateStats();
}

/* ---------- тест ---------- */
function buildQuiz(keepScore){
  const pool = deckItems(state.deck);
  const usePool = pool.length >= 4 ? pool : GLOSSARY.slice();
  const prevAsked = (state.quiz && keepScore) ? state.quiz.asked : new Set();
  const score = (state.quiz && keepScore) ? state.quiz.score : { ok: 0, bad: 0, streak: 0 };

  let fresh = usePool.filter(g => !prevAsked.has(g.ko));
  if (!fresh.length){ prevAsked.clear(); fresh = usePool; }
  const correct = fresh[Math.floor(Math.random() * fresh.length)];
  prevAsked.add(correct.ko);

  const distractors = usePool.filter(g => g.ko !== correct.ko)
    .sort(() => Math.random() - .5).slice(0, 3);
  while (distractors.length < 3){
    const g = GLOSSARY[Math.floor(Math.random() * GLOSSARY.length)];
    if (g.ko !== correct.ko && !distractors.includes(g)) distractors.push(g);
  }
  const options = distractors.concat([correct]).sort(() => Math.random() - .5);
  state.quiz = { correct, options, answered: false, asked: prevAsked, score };
  renderQuiz();
}
function renderQuiz(){
  const q = state.quiz;
  if (!q) return;
  const koFirst = state.mode !== 'ru-ko';
  $('quizQ').textContent = koFirst ? q.correct.ko : q.correct.ru;
  const d = deckMeta(q.correct.deck);
  const badge = $('quizBadge');
  badge.style.background = d.color + '1f'; badge.style.color = d.color;
  badge.style.border = '1px solid ' + d.color + '55';
  badge.textContent = d.icon + ' ' + d.label;

  const box = $('quizOptions');
  box.innerHTML = '';
  q.options.forEach(opt => {
    const b = document.createElement('button');
    b.className = 'quiz-opt';
    b.textContent = koFirst ? opt.ru : opt.ko;
    b.onclick = () => answerQuiz(b, opt);
    box.appendChild(b);
  });

  const fb = $('quizFeedback');
  fb.textContent = ''; fb.className = 'quiz-feedback';
  $('quizNext').classList.add('hidden');
  $('quizOk').textContent = q.score.ok;
  $('quizBad').textContent = q.score.bad;
  $('quizStreak').textContent = q.score.streak;
}
function answerQuiz(btn, opt){
  const q = state.quiz;
  if (!q || q.answered) return;
  q.answered = true;
  const koFirst = state.mode !== 'ru-ko';
  const right = opt.ko === q.correct.ko;
  document.querySelectorAll('.quiz-opt').forEach(b => {
    b.disabled = true;
    const isCorrect = koFirst ? b.textContent === q.correct.ru : b.textContent === q.correct.ko;
    if (isCorrect) b.classList.add('correct');
  });
  const fb = $('quizFeedback');
  if (right){
    q.score.ok++; q.score.streak++;
    fb.textContent = ['Верно! 🎉', 'Отлично! 💪', 'Точно! ✨', 'Есть! 👏'][Math.floor(Math.random()*4)];
    fb.className = 'quiz-feedback ok';
    speak(q.correct.ko, 'ko-KR');
  } else {
    btn.classList.add('wrong');
    q.score.bad++; q.score.streak = 0;
    fb.textContent = 'Правильный ответ: ' + (koFirst ? q.correct.ru : q.correct.ko);
    fb.className = 'quiz-feedback bad';
  }
  $('quizOk').textContent = q.score.ok;
  $('quizBad').textContent = q.score.bad;
  $('quizStreak').textContent = q.score.streak;
  $('quizNext').classList.remove('hidden');
}

/* ---------- глоссарий ---------- */
function renderGlossary(){
  const q = state.search.trim().toLowerCase();
  let list = deckItems(state.deck);
  if (q){
    list = list.filter(g =>
      g.ko.toLowerCase().includes(q) ||
      g.ru.toLowerCase().includes(q) ||
      (g.hint || '').toLowerCase().includes(q));
  }
  $('searchCount').textContent = 'Найдено: ' + list.length;
  const box = $('glossaryList');
  box.innerHTML = '';
  if (!list.length){
    box.innerHTML = '<div class="empty-note">Ничего не найдено. Измените запрос или выберите другую колоду.</div>';
    return;
  }
  list.forEach((g, i) => {
    const d = deckMeta(g.deck);
    const row = document.createElement('div');
    row.className = 'g-row';
    row.innerHTML =
      `<div class="g-top">
        <div class="g-main">
          <div class="g-ko">${g.ko}</div>
          <div class="g-ru">${g.ru}</div>
        </div>
        <div class="g-right">
          <span class="g-badge" style="background:${d.color}1f;color:${d.color};border:1px solid ${d.color}55">${d.icon}</span>
          <button class="g-star${state.favs.has(g.ko) ? ' active' : ''}" title="В избранное">${state.favs.has(g.ko) ? '★' : '☆'}</button>
          <button class="icon-btn" style="width:32px;height:32px;font-size:14px" title="Озвучить">🔊</button>
        </div>
      </div>
      <div class="g-detail">
        <div class="g-hint">${g.hint || ''}</div>
        ${g.exKor ? `<div class="g-exkor">${g.exKor}</div>${g.exRus ? `<div class="g-exru">${g.exRus}</div>` : ''}` : ''}
      </div>`;
    row.querySelector('.g-top').onclick = () => { if (!hasSelection()) row.classList.toggle('open'); };
    row.querySelector('.g-star').onclick = e => {
      e.stopPropagation();
      state.favs.has(g.ko) ? state.favs.delete(g.ko) : state.favs.add(g.ko);
      LS.set('la_favs', [...state.favs]);
      const st = row.querySelector('.g-star');
      st.classList.toggle('active', state.favs.has(g.ko));
      st.textContent = state.favs.has(g.ko) ? '★' : '☆';
      buildChips(); updateStats();
    };
    row.querySelector('.icon-btn').onclick = e => { e.stopPropagation(); speak(g.ko, 'ko-KR'); };
    box.appendChild(row);
  });
}

/* ---------- диалоги ---------- */
function renderDialogues(){
  const box = $('dialogueList');
  box.innerHTML = '';
  DIALOGUES.forEach(block => {
    const div = document.createElement('div');
    div.className = 'dlg-block';
    div.innerHTML = `<h3>${block.title}</h3>`;
    block.items.forEach(item => {
      const row = document.createElement('div');
      row.className = 'dlg-card';
      row.innerHTML =
        `<button class="dlg-speak" title="Озвучить">🔊</button>
         <div><div class="dlg-ko">${item.ko}</div><div class="dlg-ru">${item.ru}</div></div>`;
      row.querySelector('.dlg-speak').onclick = () => speak(item.ko, 'ko-KR');
      div.appendChild(row);
    });
    box.appendChild(div);
  });
}

/* ---------- аудио ---------- */
function renderListen(){
  const box = $('listenList');
  box.innerHTML = '';
  const list = deckItems(state.deck);
  if (!list.length){ box.innerHTML = '<div class="empty-note">В этой колоде пока нет слов.</div>'; return; }
  list.forEach(g => {
    const row = document.createElement('div');
    row.className = 'g-row';
    row.style.cursor = 'default';
    row.innerHTML =
      `<div class="g-top">
        <button class="icon-btn" style="width:40px;height:40px" title="Озвучить">🔊</button>
        <div class="g-main">
          <div class="g-ko">${g.ko}</div>
          <div class="g-ru">${g.ru}</div>
        </div>
        <span class="g-badge" style="background:${deckMeta(g.deck).color}1f;color:${deckMeta(g.deck).color};border:1px solid ${deckMeta(g.deck).color}55">${deckMeta(g.deck).icon}</span>
      </div>`;
    row.querySelector('.icon-btn').onclick = () => speak(g.ko, 'ko-KR');
    box.appendChild(row);
  });
}

/* ---------- цитата дня ---------- */
function todayStr(){ return new Date().toISOString().slice(0, 10); }
function showQuote(){
  if (!QUOTES.length) return;
  let q = state.quote;
  if (!q || q.date !== todayStr()){
    q = { date: todayStr(), idx: Math.floor(Math.random() * QUOTES.length) };
    state.quote = q; LS.set('la_quote', q);
  }
  const item = QUOTES[q.idx];
  $('quoteStrip').innerHTML =
    `<span>💬</span><span><span class="q-ko">${item.kor}</span> — <span class="q-ru">${item.rus}</span></span><span class="q-next">↻</span>`;
}
function nextQuote(){
  if (!QUOTES.length) return;
  const cur = state.quote ? state.quote.idx : -1;
  const idx = (cur + 1 + Math.floor(Math.random() * 2)) % QUOTES.length;
  state.quote = { date: todayStr(), idx };
  LS.set('la_quote', state.quote);
  showQuote();
}

/* ---------- переключение видов ---------- */
function switchView(v){
  state.view = v;
  document.querySelectorAll('.view').forEach(s => s.classList.toggle('hidden', s.id !== 'view-' + v));
  document.querySelectorAll('.tab').forEach(b => b.classList.toggle('active', b.dataset.view === v));
  if (v === 'quiz' && !state.quiz) buildQuiz(false);
  window.scrollTo({ top: 0 });
}

/* ---------- клавиатура и свайпы ---------- */
document.addEventListener('keydown', e => {
  if (state.view !== 'cards') return;
  if (e.key === 'ArrowRight') nextCard();
  else if (e.key === 'ArrowLeft') prevCard();
  else if (e.key === ' '){ e.preventDefault(); $('cardEl').classList.toggle('flipped'); }
  else if (e.key.toLowerCase() === 'f') toggleFav();
  else if (e.key.toLowerCase() === 's') speakSide('front');
  else if (e.key.toLowerCase() === 'r') randCard();
});
(function swipeInit(){
  const zone = $('cardZone');
  let x0 = null;
  zone.addEventListener('touchstart', e => { x0 = e.touches[0].clientX; }, { passive: true });
  zone.addEventListener('touchend', e => {
    if (x0 === null) return;
    const dx = e.changedTouches[0].clientX - x0;
    // выделение текста длинным нажатием — не листаем карточку
    if (!hasSelection() && Math.abs(dx) > 60){ dx < 0 ? nextCard() : prevCard(); }
    x0 = null;
  }, { passive: true });
})();

/* ---------- привязка событий ---------- */
/* Выделение текста: если пользователь выделяет слово, чтобы скопировать/перевести его,
   никакие обработчики клика не должны срабатывать */
function hasSelection(){
  const s = window.getSelection();
  return !!(s && !s.isCollapsed && String(s).trim());
}
$('cardEl').addEventListener('click', e => {
  if (e.target.closest('button')) return;
  if (hasSelection() || e.detail > 1) return;   // выделен текст или двойной клик — не переворачиваем
  $('cardEl').classList.toggle('flipped');
});
/* Двойной клик по слову выделяет его: первый клик успел перевернуть карточку —
   возвращаем исходную сторону, чтобы слово осталось на глазах */
$('cardEl').addEventListener('dblclick', () => {
  if (hasSelection()) $('cardEl').classList.toggle('flipped');
});
$('cardEl').addEventListener('keydown', e => {
  if (e.key === 'Enter') $('cardEl').classList.toggle('flipped');
});
$('prevBtn').addEventListener('click', prevCard);
$('nextBtn').addEventListener('click', nextCard);
$('randBtn').addEventListener('click', randCard);
$('quoteStrip').addEventListener('click', () => { if (!hasSelection()) nextQuote(); });
$('quizNext').addEventListener('click', () => buildQuiz(true));
$('quizReset').addEventListener('click', () => { state.quiz = null; buildQuiz(false); });
$('glossarySearch').addEventListener('input', e => { state.search = e.target.value; renderGlossary(); });
document.querySelectorAll('#modeSeg button').forEach(b => {
  b.addEventListener('click', () => {
    state.mode = b.dataset.mode;
    LS.set('la_mode', state.mode);
    document.querySelectorAll('#modeSeg button').forEach(x => x.classList.toggle('active', x === b));
    state.idx = 0; refreshItems(); renderCard();
    if (state.quiz) buildQuiz(true);
  });
});
document.querySelectorAll('.tab').forEach(b => b.addEventListener('click', () => switchView(b.dataset.view)));

/* ---------- инициализация ---------- */
applyTheme(LS.get('la_theme', 'light'));
